// src/services/uploadService.ts
export async function uploadImageService(enpoint:string,file: File): Promise<any> {
  const url = process.env.REACT_APP_API_URL ?? '';

  const formData = new FormData();
  formData.append('image', file, file.name);

  try {
    const response = await fetch(`${url}/${enpoint}`, {
      method: 'POST',
      headers: {
        // ไม่ต้องใส่ Content-Type เพราะ fetch จะจัดการให้เมื่อใช้ FormData
        'accept': '*/*',
      },
      body: formData,
    });

    if (!response.ok) {
      throw new Error(`Upload failed: ${response.statusText}`);
    }

    return await response.json(); // หรือ response.text() ถ้า API ส่งข้อความ
  } catch (error) {
    console.error('Error uploading image:', error);
    throw error;
  }
}
